  D('gift_say', 'gift', [['ให้ของขวัญ|ซื้อของมาฝาก|มีของให้|เอามาฝาก|ของฝาก|ซื้ออะไรให้|เอาให้|ให้ของ|ซื้อให้|เอา(?:ของขวัญ|ของ|ดอกไม้)?มาให้|ของขวัญมาให้|มีของขวัญ|มอบให้|ซื้อของขวัญ|นี่ของขวัญ|ให้ดอกไม้', 3]], null, { fn: 'giftSay' });
