  D('treat_me', 'help', ['เลี้ยงฉัน|เลี้ยงหน่อย|เลี้ยงข้าวฉัน|เลี้ยงกาแฟ|ใครเลี้ยง|เลี้ยงด้วย'], x => x.h >= 6 ? ['ได้สิ{e} วันนี้เลี้ยงเอง กินอะไรดี{q}', 'เอาเลย{e} เดี๋ยวเลี้ยงเอง'] : ['รอบนี้ต่างคนต่างจ่ายนะ{e} 555', 'ยังไม่ถึงขั้นเลี้ยงกันเลยนะ{e} 😅']);
