  D('buy_sell', 'job', ['อยากซื้อ|อยากขาย|รับซื้อ|ขายให้|ซื้อที่ไหน|ขายที่ไหน|ซื้อของที่ไหน|ขายของที่ไหน|มีขายไหม'], ['ถ้าอยากซื้อของแนะนำที่ตลาดกับร้านค้าในหมู่บ้าน{e} ขายผักที่ตลาดริมทะเลได้ราคาดี', 'ขายผักส่งที่กล่องหน้าบ้านก็ได้{e} หรือไปตลาดริมทะเลได้ +50%']);
